    op = operator[i]
    next_operand = operand[i + 1]

    # Perform the operation based on the operator
    if op == '+':
        result += next_operand
    elif op == '-':
        result -= next_operand
    elif op == '*':
        result *= next_operand
    elif op == '//':
        result //= next_operand
    elif op == '**':
